import java.util.Scanner;
public class JNestedIfTemperature2 {
	public static void main(String[] args) {
		//Khatwa 1: Qira'at darajat al-harara lil-yawm wa al-ams
		Scanner scan = new Scanner (System.in);
		System.out.println("Adkhul darajat al-harara li-l-ams: ");
		double yesterday = scan.nextDouble();
		System.out.println("Adkhul darajat al-harara li-l-yawm: ");
		double today = scan.nextDouble();		
		//Khatwa 2: Qira'at al-rutuba lil-yawm wa al-ams
		System.out.println("Adkhul rutubat al-ams: ");
		double humidityYesterday = scan.nextDouble();
		System.out.println("Adkhul rutubat al-yawm: ");
		double humidityToday = scan.nextDouble();
		scan.close();
		//Khatwa 3: Tanzir al-mustakhdim bi-taghyurat darajat al-harara
		if ( today < yesterday ) {
			System.out.println("Al-jaww yusbih abrad!");
		} else {
			if ( today > yesterday) {
				//Khatwa 3.1: Ta'yin wa tanzir al-mustakhdim bi-taghyurat al-rutuba 3ndama yusbih al-jaww askhana
				if ( humidityToday < humidityYesterday ) {
					System.out.println("Al-jaww yusbih askhana walakin akall rutuba!");
				} else if ( humidityToday > humidityYesterday ) {
					System.out.println("Al-jaww yusbih askhana wa akthar rutuba!");
				} else {
					System.out.println("Al-jaww yusbih askhana walakin rutuba lam tataghayyar!");
				}
			} else {
				System.out.println("Darajat al-harara nafs al-ams!");
			}
		}
	}
}
